   feature_report={k:self.report[k] for k in ['schema_version','created_at','compiler','reference_compiler','inputs']};feature_report.update(kind='features',status='assessed',commands=self.report['reproduction_commands'],evidence=[relative(self.report_path)],features=[{**f,'status':'partial'} for f in features]+[dict(name=c['id'].split('/',1)[1],status='unsupported',evidence_cases=[c['id']]) for c in self.report['cases'] if c['outcome']=='unsupported_language']);(ROOT/'reports/features'/(self.run_id+'.json')).write_text(json.dumps(feature_report,indent=2)+'\n')
